import os

# Read the actual .env file
env_path = os.path.expanduser("~/.config/feishu/.env")
config = {}
with open(env_path) as f:
    for line in f:
        line = line.strip()
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            config[key] = value

# Show keys available (masking secrets)
for k, v in config.items():
    if "SECRET" in k or "KEY" in k or "TOKEN" in k:
        print(f"{k}: {'*' * 20}{v[-10:]}")
    else:
        print(f"{k}: {v}")
"}

