# Check all possible config sources
paths = [
    '/root/.config/feishu/.env',
    '/root/.config/feishu/.env.example',
]

for p in paths:
    try:
        with open(p) as f:
            content = f.read()
        if 'WEBHOOK' in content:
            for line in content.split('\n'):
                if 'WEBHOOK' in line and '=' in line:
                    print(line)
    except:
        pass

# Also check if there's a FEISHU_NOTIFY_GROUP or other IDs stored anywhere
import os
for root, dirs, files in os.walk('/root/.config/feishu'):
    for fn in files:
        if fn.endswith('.json') or fn.endswith('.txt'):
            try:
                with open(os.path.join(root, fn)) as f:
                    content = f.read()
                    if 'oc' in content.lower() and ('chat' in content.lower() or 'group' in content.lower()):
                        print(f"\n{os.path.join(root, fn)}:")
                        print(content[:500])
            except:
                pass
"}

